:root {
  --bg: #1b1f2a;
  --bg-accent: #232a3a;
  --card: #f8fafc;
  --text: #1e293b;
  --muted: #64748b;
  --border: #e2e8f0;
  --accent: #4f46e5;
  --accent-hover: #4338ca;
  --accent-press: #3730a3;
  --focus: #f59e0b;
  --radius: 14px;
  --shadow: 0 18px 45px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: radial-gradient(circle at 15% 15%, var(--bg-accent), var(--bg) 60%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  width: 100%;
  max-width: 760px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 28px;
}

.header h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 1rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}

.swatch {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.swatch-color {
  height: 110px;
  border-radius: 10px;
  border: 1px solid var(--border);
  transition: transform 120ms ease, box-shadow 120ms ease;
}

.swatch-color:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.15);
}

.swatch-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
}

.hex {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  word-break: break-all;
  text-align: center;
}

.lock-btn {
  appearance: none;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--muted);
  font: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 999px;
  cursor: pointer;
  min-height: 32px;
  transition: background 120ms ease, color 120ms ease, border-color 120ms ease, transform 80ms ease;
}

.lock-btn:hover {
  background: #f1f5f9;
  color: var(--text);
  border-color: #cbd5e1;
}

.lock-btn:active {
  transform: scale(0.97);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.actions {
  display: flex;
  justify-content: center;
}

.btn {
  appearance: none;
  border: none;
  background: var(--accent);
  color: #fff;
  font: inherit;
  font-weight: 700;
  font-size: 1.05rem;
  padding: 14px 28px;
  border-radius: 10px;
  cursor: pointer;
  min-height: 48px;
  transition: background 120ms ease, transform 80ms ease, box-shadow 120ms ease;
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:active {
  background: var(--accent-press);
  transform: translateY(1px);
  box-shadow: 0 2px 6px rgba(79, 70, 229, 0.3);
}

.btn:focus-visible,
.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.hint {
  margin: 18px 0 0;
  text-align: center;
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 600px) {
  .card {
    padding: 20px;
  }

  .palette {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .swatch-color {
    height: 90px;
  }
}

@media (max-width: 380px) {
  .palette {
    grid-template-columns: 1fr;
  }

  .swatch {
    flex-direction: row;
    align-items: center;
  }

  .swatch-color {
    width: 64px;
    height: 64px;
    flex: 0 0 auto;
  }

  .swatch-meta {
    flex: 1;
    flex-direction: row;
    justify-content: space-between;
  }

  .hex {
    text-align: left;
  }
}

(function () {
  "use strict";

  var paletteEl = document.getElementById("palette");
  var generateBtn = document.getElementById("generateBtn");
  var hintEl = document.getElementById("hint");

  var SWATCH_COUNT = 5;
  var state = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0;
    var g = 0;
    var b = 0;

    if (h >= 0 && h < 60) { r = c; g = x; b = 0; }
    else if (h < 120) { r = x; g = c; b = 0; }
    else if (h < 180) { r = 0; g = c; b = x; }
    else if (h < 240) { r = 0; g = x; b = c; }
    else if (h < 300) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }

    function toHex(v) {
      var n = Math.round((v + m) * 255);
      var str = n.toString(16);
      return str.length === 1 ? "0" + str : str;
    }

    return "#" + toHex(r) + toHex(g) + toHex(b);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function createHarmoniousPalette() {
    var baseHue = randomInt(0, 359);
    var scheme = randomInt(0, 2);
    var hues = [];

    if (scheme === 0) {
      // Analogous: tight hue spread
      for (var i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + i * 24 + randomInt(-8, 8) + 360) % 360);
      }
    } else if (scheme === 1) {
      // Complementary split
      var comp = (baseHue + 180) % 360;
      hues = [
        baseHue,
        (baseHue + 30) % 360,
        comp,
        (comp + 30) % 360,
        (baseHue + 60) % 360
      ];
    } else {
      // Triadic-ish spread
      hues = [
        baseHue,
        (baseHue + 120) % 360,
        (baseHue + 240) % 360,
        (baseHue + 60) % 360,
        (baseHue + 180) % 360
      ];
    }

    var colors = [];
    for (var j = 0; j < SWATCH_COUNT; j++) {
      var sat = randomInt(55, 80);
      var light = randomInt(40, 65);
      colors.push(hslToHex(hues[j], sat, light));
    }
    return colors;
  }

  function initState() {
    var colors = createHarmoniousPalette();
    state = colors.map(function (color) {
      return { color: color, locked: false };
    });
  }

  function regenerate() {
    var fresh = createHarmoniousPalette();
    var changed = false;
    for (var i = 0; i < state.length; i++) {
      if (!state[i].locked) {
        state[i].color = fresh[i];
        changed = true;
      }
    }
    render();
    hintEl.textContent = changed
      ? "New palette generated. Locked colors were kept."
      : "All swatches are locked. Unlock one to generate new colors.";
  }

  function toggleLock(index) {
    state[index].locked = !state[index].locked;
    render();
    var lockedCount = state.filter(function (s) { return s.locked; }).length;
    hintEl.textContent = lockedCount === SWATCH_COUNT
      ? "All swatches are locked. Unlock one to generate new colors."
      : "Swatch " + (index + 1) + (state[index].locked ? " locked." : " unlocked.");
  }

  function render() {
    paletteEl.innerHTML = "";

    state.forEach(function (item, index) {
      var swatch = document.createElement("div");
      swatch.className = "swatch";

      var colorBox = document.createElement("div");
      colorBox.className = "swatch-color";
      colorBox.style.backgroundColor = item.color;
      colorBox.setAttribute("aria-hidden", "true");

      var meta = document.createElement("div");
      meta.className = "swatch-meta";

      var hex = document.createElement("span");
      hex.className = "hex";
      hex.textContent = item.color;

      var lockBtn = document.createElement("button");
      lockBtn.type = "button";
      lockBtn.className = "lock-btn";
      lockBtn.setAttribute("aria-pressed", String(item.locked));
      lockBtn.setAttribute(
        "aria-label",
        (item.locked ? "Unlock" : "Lock") + " swatch " + (index + 1) + " " + item.color
      );
      lockBtn.textContent = item.locked ? "Locked" : "Lock";
      lockBtn.addEventListener("click", function () {
        toggleLock(index);
      });

      meta.appendChild(hex);
      meta.appendChild(lockBtn);
      swatch.appendChild(colorBox);
      swatch.appendChild(meta);
      paletteEl.appendChild(swatch);
    });
  }

  generateBtn.addEventListener("click", regenerate);

  initState();
  render();
})();
